            writer.WriteNumber("ankama_id", monster.AnkamaId);

            writer.WriteString("name", monster.Name);

            writer.WritePropertyName("race");
            JsonSerializer.Serialize(writer, monster.Race, jsonSerializerOptions);
            writer.WritePropertyName("grades");
            JsonSerializer.Serialize(writer, monster.Grades, jsonSerializerOptions);
            writer.WritePropertyName("spawn_locations");
            JsonSerializer.Serialize(writer, monster.SpawnLocations, jsonSerializerOptions);
            writer.WritePropertyName("drops");
            JsonSerializer.Serialize(writer, monster.Drops, jsonSerializerOptions);
            if (monster.ImageUrlsOption.IsSet)
            {
                writer.WritePropertyName("image_urls");
                JsonSerializer.Serialize(writer, monster.ImageUrls, jsonSerializerOptions);
            }
            if (monster.GlobalDropsOption.IsSet)
            {
                writer.WritePropertyName("global_drops");
                JsonSerializer.Serialize(writer, monster.GlobalDrops, jsonSerializerOptions);
            }
            if (monster.AppearanceOption.IsSet)
            {
                writer.WritePropertyName("appearance");
                JsonSerializer.Serialize(writer, monster.Appearance, jsonSerializerOptions);
            }
            if (monster.IsBountyOption.IsSet)
                writer.WriteBoolean("is_bounty", monster.IsBountyOption.Value!.Value);

            if (monster.CorrespondingMiniBossOption.IsSet)
            {
                writer.WritePropertyName("corresponding_mini_boss");
                JsonSerializer.Serialize(writer, monster.CorrespondingMiniBoss, jsonSerializerOptions);
            }
            if (monster.SummonCostOption.IsSet)
                writer.WriteNumber("summon_cost", monster.SummonCostOption.Value!.Value);

            if (monster.SpeedAdjustOption.IsSet)
                writer.WriteNumber("speed_adjust", monster.SpeedAdjustOption.Value!.Value);

            if (monster.ScaleGradeReferenceOption.IsSet)
                writer.WriteNumber("scale_grade_reference", monster.ScaleGradeReferenceOption.Value!.Value);

            if (monster.AchievementsOption.IsSet)
            {
                writer.WritePropertyName("achievements");
                JsonSerializer.Serialize(writer, monster.Achievements, jsonSerializerOptions);
            }
            if (monster.SoulsOption.IsSet)
            {
                writer.WritePropertyName("souls");
                JsonSerializer.Serialize(writer, monster.Souls, jsonSerializerOptions);
            }
            if (monster.CharacteristicRatiosOption.IsSet)
            {
                writer.WritePropertyName("characteristic_ratios");
                JsonSerializer.Serialize(writer, monster.CharacteristicRatios, jsonSerializerOptions);
            }
        }
    }
